(
int
i=
1
; i<RB_CAPS; i++)
     {
if
(caps[i]<smallest)
        {
         smallest=caps[i];
         cap=(ENUM_RB_CAP)i;
        }
     }
   volume=RoundDown(smallest,vol_step);
if
(volume<vol_min-
1e-8
)
     {
      volume=
0.0
;
return
(RB_BELOW_MIN);
     }
return
(RB_OK);
  }
RoundDown() rounds down to the volume step. The 1e-7 covers a floating-point case. With a step of 0.1, 0.3 divides to 2.9999999999999996, and a plain MathFloor() would turn a valid 0.3 lots into 0.2.
//+------------------------------------------------------------------+
//| RoundDown: largest volume on the step grid not above volume      |
//+------------------------------------------------------------------+
double
CRiskBudget::RoundDown(
const
double
volume,
const
double
step)
  {
