(
0.0
);
//--- the small epsilon keeps 0.3/0.1 at 3 steps instead of 2
double
lots=
MathFloor
(volume/step+
1e-7
)*step;
return
(
NormalizeDouble
(lots,StepDigits(step)));
  }
